const fs = require('fs');
const crypto = require('crypto');

async function decryptLTR(inputPath, passphrase, outputPath) {
 const buf = fs.readFileSync(inputPath);
 let offset = 0;

 // Read header
 const magic = buf.toString('ascii', 0, 3);
 if (magic !== 'LTR') throw new Error('Not an LTR file');
 offset = 3;

 const version = buf[offset++];
 if (version !== 1) throw new Error('Unsupported LTR version: ' + version);

 const saltLen = buf.readUInt16BE(offset); offset += 2;
 const salt = buf.subarray(offset, offset + saltLen); offset += saltLen;

 const nameLen = buf.readUInt16BE(offset); offset += 2;
 const fileName = buf.subarray(offset, offset + nameLen).toString('utf8'); offset += nameLen;

 const mimeLen = buf[offset++];
 const mimeType = buf.subarray(offset, offset + mimeLen).toString('ascii'); offset += mimeLen;

 const fileSize = buf.readBigUInt64BE(offset); offset += 8;
 const chunkCount = buf.readUInt32BE(offset); offset += 4;

 // Derive key
 const key = await crypto.subtle.deriveKey(
 { name: 'PBKDF2', salt, iterations: 600000, hash: 'SHA-256' },
 await crypto.subtle.importKey('raw', new TextEncoder().encode(passphrase), 'PBKDF2', false, ['deriveKey']),
 { name: 'AES-GCM', length: 256 },
 false,
 ['decrypt']
 );

 // Decrypt chunks
 const output = [];
 for (let i = 0; i < chunkCount; i++) {
 const iv = buf.subarray(offset, offset + 12); offset += 12;
 const encData = buf.subarray(offset); // rest is encrypted (GCM includes auth tag)
 const aad = Buffer.alloc(4); aad.writeUInt32BE(i);

 const dec = await crypto.subtle.decrypt(
 { name: 'AES-GCM', iv, additionalData: aad },
 key,
 encData.slice(0, encData.length) // will fail if we don't know exact boundary
 );
 // NOTE: For multi-chunk files, you need to know each chunk's encrypted size.
 // The Web Worker tracks this; for standalone scripts, chunk boundaries must be computed.
 // Each AES-GCM ciphertext = plaintext.length + 16 bytes (auth tag)
 // For 1MiB chunks: last chunk may be smaller.
 output.push(new Uint8Array(dec));
 offset += new Uint8Array(dec).length + 16; // plaintext + 16 byte auth tag
 }

 fs.writeFileSync(outputPath || fileName, Buffer.concat(output));
 console.log('Decrypted:', fileName, mimeType, fileSize.toString(), 'bytes');
}

decryptLTR(process.argv[2], process.argv[3], process.argv[4]).catch(console.error);
